-- Necromancer (class 10) Phase 2 batch 3 (minions, slice 1):
-- Raise Ghoul (61024), Raise Skeleton (61025), Tether (61026).
-- Generated by tools/generate_phase2_batch3_minions.py; re-runnable.
--
-- Raise Ghoul/Skeleton are guardian summons (SPELL_EFFECT_SUMMON_GUARDIAN)
-- of creature 846/6412; the module re-levels/scales the minion to the
-- caster (script_name spell_necromancer_raise_minion).
-- Tether is a friendly-target dummy spell; the module replaces the
-- target guardian with a permanent, controllable pet
-- (script_name spell_necromancer_tether).

-- NOTE: no playercreateinfo and no spell_chain changes - all three are
-- single-rank and learned by the module at level 14/14/20.

DELETE FROM `spell_template` WHERE `entry` IN (61024, 61025, 61026);
DELETE FROM `skill_line_ability` WHERE `skill_id` = 700 AND `spell_id` IN (61024, 61025, 61026);

